// Identify the source file and check whether it was already registered in the sheet
// Identifica o arquivo de origem e verifica se ele já foi registrado na planilha
const source = $('INGEST — PDF Document').first();
const fileId = source.json.id;

// Rows read from Google Sheets (column "id_relatorio" stores the Drive file ID)
// Linhas lidas do Google Sheets (a coluna "id_relatorio" guarda o ID do arquivo no Drive)
const rows = $input.all();

const isDuplicate = Boolean(
  fileId &&
  rows.some(row => row.json?.id_relatorio === fileId)
);

return [
  {
    json: {
      ...source.json,
      file_id: fileId,
      duplicate: isDuplicate,
      dedup_status: isDuplicate ? 'DUPLICATE' : 'NEW'
    },

    // IMPORTANT: keep the original PDF binary so the AI node can read it
    // IMPORTANTE: preserva o binário do PDF para o nó de IA conseguir lê-lo
    binary: source.binary
  }
];

