const items = $input.all();
const results = [];

const requiredFields = [
  'cnes',
  'placa',
  'tipologia',
  'compet',
  'uf',
  'municipio',
  'oci',
  'quantidade'
];

for (const item of items) {

  const input = item.json;

  // ============================================================
  // 1. Get the model response (Anthropic returns content[0].text)
  // ============================================================

  const rawText = input.content?.[0]?.text;

  if (typeof rawText !== 'string' || !rawText.trim()) {
    results.push({
      json: {
        valid: false,
        validation_status: 'FAILED',
        total_records: 0,
        errors: ['No usable AI response was found.']
      }
    });
    continue;
  }

  // ============================================================
  // 2. Parse JSON (strip Markdown fences if the model adds them)
  // ============================================================

  let data;

  try {
    const cleaned = rawText
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    data = JSON.parse(cleaned);
  } catch (error) {
    results.push({
      json: {
        valid: false,
        validation_status: 'FAILED',
        total_records: 0,
        errors: ['AI response is not valid JSON.', error.message],
        raw_response: rawText
      }
    });
    continue;
  }

  // ============================================================
  // 3. Validate root structure
  // ============================================================

  const errors = [];

  if (typeof data !== 'object' || data === null || Array.isArray(data)) {
    errors.push('AI response must be a JSON object.');
  }

  const records = data?.atendimentos;

  if (!Array.isArray(records)) {
    errors.push('The "atendimentos" field must be an array.');
  } else {

    if (records.length === 0) {
      errors.push('No attendance records were found.');
    }

    // ==========================================================
    // 4. Validate each record
    // ==========================================================

    records.forEach((record, index) => {

      if (typeof record !== 'object' || record === null || Array.isArray(record)) {
        errors.push(`Attendance ${index} must be a JSON object.`);
        return;
      }

      // Required fields and empty strings (null is allowed)
      for (const field of requiredFields) {
        if (!Object.prototype.hasOwnProperty.call(record, field)) {
          errors.push(`Missing field: atendimentos[${index}].${field}`);
        } else if (record[field] === '') {
          errors.push(`Empty field: atendimentos[${index}].${field}`);
        }
      }

      // A record with every field null carries no information
      if (requiredFields.every(f => record[f] === null || record[f] === undefined)) {
        errors.push(`Attendance ${index} has no data.`);
      }

      // Quantity must be a non-negative integer
      const quantidade = record.quantidade;

      if (quantidade !== null && quantidade !== undefined) {
        if (
          typeof quantidade !== 'number' ||
          !Number.isInteger(quantidade) ||
          quantidade < 0
        ) {
          errors.push(`Invalid quantity at atendimentos[${index}]: ${quantidade}`);
        }
      }

      // Unexpected fields
      for (const field of Object.keys(record)) {
        if (!requiredFields.includes(field)) {
          errors.push(`Unexpected field: atendimentos[${index}].${field}`);
        }
      }
    });
  }

  // ============================================================
  // 5. Final result
  // ============================================================

  results.push({
    json: {
      valid: errors.length === 0,
      validation_status: errors.length === 0 ? 'PASSED' : 'FAILED',
      total_records: Array.isArray(records) ? records.length : 0,
      errors,
      data
    }
  });
}

return results;

const input = $input.first().json;

// Original document information (from the Google Drive download)
// Informações do documento original (vindas do download no Google Drive)
const source = $('INGEST — PDF Document').first().json;

// Validated attendance records
// Registros de atendimento validados
const atendimentos = input.data?.atendimentos || [];

// One n8n item per attendance
// Um item do n8n para cada atendimento
return atendimentos.map((record, index) => ({
  json: {

    // Extracted fields / Campos extraídos pela IA
    cnes: record.cnes ?? null,
    placa: record.placa ?? null,
    tipologia: record.tipologia ?? null,
    compet: record.compet ?? null,
    uf: record.uf ?? null,
    municipio: record.municipio ?? null,
    oci: record.oci ?? null,
    qtd: record.quantidade ?? null,

    // Technical pipeline fields / Campos técnicos do pipeline
    atendimento: `ATD-${String(index + 1).padStart(4, '0')}`,
    id_relatorio: source.id ?? null,
    file_name: source.name ?? null,
    data_processamento: new Date().toISOString(),
    valid: input.valid === true
  }
}));

// Build validation error report
// Cria o relatório de erro da validação

const input = $input.first().json;

// Original document information
// Informações do documento original
const source = $('INGEST — PDF Document').first().json;

return [
  {
    json: {
      status: 'FAILED',
      validation_status: input.validation_status || 'FAILED',

      file_id: source.id || null,
      file_name: source.name || null,

      total_records: input.total_records ?? 0,

      errors: Array.isArray(input.errors)
        ? input.errors
        : ['Unknown validation error / Erro de validação desconhecido'],

      timestamp: new Date().toISOString()
    }
  }
];

